"""Semantic version ordering."""


def key(version):
    """Sort key: a pre-release (1.0.0-alpha) sorts before its release (1.0.0)."""
    core, _, pre = version.partition("-")
    nums = tuple(int(x) for x in core.split("."))
    # Release (no pre-release tag) gets flag 1 so it sorts after any pre-release
    # with the same core version, which gets flag 0.
    if pre:
        return nums + (0, pre)
    return nums + (1, "")

